import java.io.*;import java.math.*;import java.security.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;class Result {public static int connectedCell(List<List<Integer>> matrix) {int n = matrix.size();if (n == 0) return 0;int m = matrix.get(0).size();int maxRegion = 0;for (int i = 0; i < n; i++) {for (int j = 0; j < m; j++) {if (matrix.get(i).get(j) == 1) {maxRegion = Math.max(maxRegion, dfs(matrix, i, j, n, m));}}}return maxRegion;}private static int dfs(List<List<Integer>> matrix, int r, int c, int n, int m) {if (r < 0 || r >= n || c < 0 || c >= m || matrix.get(r).get(c) == 0) {return 0;}matrix.get(r).set(c, 0);int count = 1;for (int dr = -1; dr <= 1; dr++) {for (int dc = -1; dc <= 1; dc++) {if (dr == 0 && dc == 0) continue;count += dfs(matrix, r + dr, c + dc, n, m);}}return count;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int n = Integer.parseInt(bufferedReader.readLine().trim());int m = Integer.parseInt(bufferedReader.readLine().trim());List<List<Integer>> matrix = new ArrayList<>();for (int i = 0; i < n; i++) {String[] matrixRowTempItems = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");List<Integer> matrixRowItems = new ArrayList<>();for (int j = 0; j < m; j++) {int matrixItem = Integer.parseInt(matrixRowTempItems[j]);matrixRowItems.add(matrixItem);}matrix.add(matrixRowItems);}int result = Result.connectedCell(matrix);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}